/**
 * Brief 10: personalised revision. Quick review, weak-topic practice, explore and mixed practice.
 *
 * This sits ON TOP of the Brief 04 spaced-review machinery and does not replace it:
 *   - what can be asked comes from `ReviewService.candidates` (templates bound to lessons the learner has completed, in that lesson's own
 *     teaching scope), generated by `ReviewService.generateFor` and resolved by `ReviewService.resolve`, so nothing untaught can appear and
 *     a question whose generator changed is dropped, never regraded;
 *   - what is WEAK, DUE or UNTESTED is read from the existing evidence ledger (`concept_mastery`, `mastery_evidence`) plus the learner's
 *     independent mock-examination results;
 *   - a first answer to a revision question is recorded as the same kind of independent evidence a review answer is (`review-item`), so the
 *     spaced schedule keeps working. Weak-topic practice is the exception: the learner has just been shown an explanation, so its answers are
 *     recorded as `remedial-step` (learning, never mastery evidence).
 * The existing Review hub and its sessions are untouched. XP and the daily goal use the same ledger, source-keyed per session, so a retried
 * "finish" can never pay twice.
 */
import { parseGeneratedItemId } from "@mtp/engine";
import type { Clock } from "./clock.ts";
import { daysBetween } from "./clock.ts";
import type { Course, LearnerItem } from "./course.ts";
import type { Db } from "./db.ts";
import { tx } from "./db.ts";
import type { Engagement } from "./engagement.ts";
import { ApiError } from "./errors.ts";
import { gradeResponse, revealSolution, type Response } from "./grade.ts";
import { isDue, type ConceptMastery } from "./mastery.ts";
import { learnerTime } from "./mastery-service.ts";
import { DEFAULT_PREP, type PrepConfig } from "./prep-config.ts";
import type { PrepService } from "./prep.ts";
import { questionKey, visibleKey } from "./question-key.ts";
import type { Candidate, SessionItem } from "./review.ts";
import { placedGradeOf } from "./path-state.ts";
import { taughtNodes } from "./taught.ts";
import { REVIEW_NODE } from "./xp.ts";

export type RevisionMode = "quick" | "weak" | "explore" | "mixed";
export type ConceptStatus = "weak" | "due" | "untested" | "learning" | "solid";
export type Trend = "improving" | "steady" | "declining" | "none";

export interface ConceptInsight {
  conceptId: string;
  title: string;
  grade: number;
  domain: string;
  status: ConceptStatus;
  trend: Trend;
  /** Why it is listed, in the learner's terms. */
  reasons: string[];
  state: string;
  lapses: number;
  recentWrong: number;
  recentTotal: number;
  topMistake: { label: string; tip: string } | null;
  lessons: Array<{ nodeId: string; title: string }>;
  /** True when a recent independent mock examination also found this topic weak. */
  examWeak: boolean;
  /** Reachable only because the learner placed above it: the lesson itself has not been completed. */
  earlierGrade: boolean;
  priority: number;
}

export interface RevisionParams {
  minutes?: number;
  conceptId?: string;
  grade?: number;
  unitId?: string;
  familyId?: string;
}

interface RevItem extends SessionItem {
  reason: "due" | "weak" | "untested" | "keep-fresh" | "explore" | "mixed";
}

interface Row {
  id: string;
  mode: RevisionMode;
  status: "open" | "complete" | "abandoned";
  params: string;
  started_at: string;
  completed_at: string | null;
  local_date: string;
  items: string;
  summary: string | null;
}

export interface RevisionSummary {
  mode: RevisionMode;
  questions: number;
  answered: number;
  firstTryCorrect: number;
  finishedEarly: boolean;
  credited: boolean;
  concepts: Array<{ conceptId: string; title: string; answered: number; firstTryCorrect: number; before: Trend | "none"; verdict: "solid" | "needs-practice"; lessons: Array<{ nodeId: string; title: string }> }>;
  today: string;
}

const seedFor = (...parts: Array<string | number>) => (hashLike(parts.join("|")) >>> 0) % 2 ** 31;
function hashLike(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export class RevisionService {
  private cfg: PrepConfig;
  constructor(
    private db: Db,
    private course: Course,
    private clock: Clock,
    private engagement: Engagement,
    private prep: PrepService | null,
    cfg: PrepConfig = DEFAULT_PREP,
  ) {
    this.cfg = cfg;
  }

  // ---- access ------------------------------------------------------------------------------------------------------------

  /** Lessons the learner has completed (at the version served now), plus every lesson of grades below an accepted placement: revising earlier-grade material is always open. */
  private accessSet(userId: string): { nodes: Set<string>; placed: number | null } {
    const nodes = taughtNodes(this.db, this.course, userId);
    const placed = placedGradeOf(this.db, userId);
    const all = new Set(nodes);
    if (placed) for (const n of this.course.nodes) if (n.grade < placed && n.type === "lesson") all.add(n.id);
    return { nodes: all, placed };
  }

  private lessonsOf(conceptId: string, limit = 2): Array<{ nodeId: string; title: string }> {
    return (this.course.ix.conceptTaughtBy.get(conceptId) ?? [])
      .filter((n) => n.type === "lesson" && this.course.isPlayable(n.id))
      .slice(0, limit)
      .map((n) => ({ nodeId: n.id, title: n.title }));
  }

  // ---- what is weak, due, untested -------------------------------------------------------------------------------------------

  /**
   * Topics a recent independent mock examination found the learner got wrong: the concepts of the questions actually missed (not every concept of the outcome).
   * The flag is a prompt to practise, not a verdict that lasts until the next full mock: it clears once the learner has since answered the topic right, first time and
   * without help, in at least two revision questions and not got one wrong.
   */
  private examWeakConcepts(userId: string): Set<string> {
    const weak = new Set<string>();
    if (!this.prep) return weak;
    const since = this.db.prepare("SELECT correct FROM revision_attempts WHERE user_id = ? AND concept_id = ? AND attempt_number = 1 AND created_at > ? ORDER BY created_at");
    for (const [conceptId, at] of this.prep.latestMockMissed(userId)) {
      const later = (since.all(userId, conceptId, at) as Array<{ correct: number }>).map((r) => r.correct === 1);
      const cleared = later.length >= 2 && later.every(Boolean);
      if (!cleared) weak.add(conceptId);
    }
    return weak;
  }

  private trendOf(recent: boolean[]): Trend {
    if (recent.length < 4) return "none";
    const last = recent.slice(-3);
    const prev = recent.slice(-6, -3);
    if (prev.length < 2) return "none";
    const wrong = (a: boolean[]) => a.filter((x) => !x).length / a.length;
    const d = wrong(prev) - wrong(last);
    return d >= 0.34 ? "improving" : d <= -0.34 ? "declining" : "steady";
  }

  /**
   * Every revisable concept (one the learner can be asked about) classified. The four statuses are mutually exclusive and in this order:
   * `weak` (repeated independent errors, a lapse, or found weak in a mock), `due` (its review date has come), `untested` (taught, but no
   * independent answer yet: unknown, NOT weak), `learning` (some evidence, still building), `solid`.
   */
  insights(userId: string): ConceptInsight[] {
    const lt = learnerTime(this.db, this.clock, userId);
    const access = this.accessSet(userId);
    const completed = taughtNodes(this.db, this.course, userId);
    const mastery = this.engagement.mastery.all(userId, lt.date);
    const examWeak = this.examWeakConcepts(userId);
    const out: ConceptInsight[] = [];
    for (const c of this.course.ix.concepts.values()) {
      if (!this.engagement.review.candidates(c.id, access.nodes).length) continue;
      const m: ConceptMastery | undefined = mastery.get(c.id);
      const recent = m?.recent ?? [];
      const window = recent.slice(-this.cfg.revision.weakWindow);
      const wrong = window.filter((x) => !x).length;
      const due = Boolean(m && isDue(m, lt.date));
      const flaggedByExam = examWeak.has(c.id);
      const weak = Boolean(m?.needsRecovery) || wrong >= this.cfg.revision.weakWrongInWindow || flaggedByExam;
      const untested = recent.length === 0 && !flaggedByExam;
      const status: ConceptStatus = weak ? "weak" : due ? "due" : untested ? "untested" : m && (m.state === "proficient" || m.state === "mastered") ? "solid" : "learning";
      const trend = this.trendOf(recent);
      const reasons: string[] = [];
      if (m?.needsRecovery) reasons.push("You missed this in a review, so it is coming back sooner.");
      if (wrong >= this.cfg.revision.weakWrongInWindow) reasons.push(`${wrong} of your last ${window.length} independent answers were not right.`);
      if (flaggedByExam) reasons.push("A recent mock examination found you missed this. Answer it right a couple of times in revision and this goes away.");
      if (due && !weak) reasons.push("It is time to check this again so it stays fresh.");
      if (untested) reasons.push("You have been taught this, but have not yet answered questions on it on your own, so we do not know yet.");
      if (trend === "improving") reasons.push("Your recent answers are better than your earlier ones.");
      const top = Object.entries(m?.mistakes ?? {}).sort((a, b) => b[1] - a[1])[0];
      const cat = top ? this.categoryOf(top[0]) : null;
      const overdue = due && m?.nextDueDate ? Math.min(30, Math.max(0, daysBetween(m.nextDueDate, lt.date))) : 0;
      const priority = (m?.needsRecovery ? 100 : 0) + (flaggedByExam ? 30 : 0) + (wrong >= this.cfg.revision.weakWrongInWindow ? 50 : 0) + (due ? 40 + overdue : 0) + (trend === "declining" ? 15 : 0) + (untested ? 12 : 0) - (status === "solid" ? 20 : 0);
      out.push({
        conceptId: c.id,
        title: c.title,
        grade: c.grade,
        domain: c.domain,
        status,
        trend,
        reasons,
        state: m?.state ?? "new",
        lapses: m?.lapses ?? 0,
        recentWrong: wrong,
        recentTotal: window.length,
        topMistake: cat,
        lessons: this.lessonsOf(c.id),
        examWeak: flaggedByExam,
        earlierGrade: !(this.course.ix.conceptTaughtBy.get(c.id) ?? []).some((n) => completed.has(n.id)),
        priority,
      });
    }
    return out.sort((a, b) => b.priority - a.priority || a.grade - b.grade || a.title.localeCompare(b.title));
  }

  private cats?: Map<string, { label: string; tip: string }>;
  private categoryOf(id: string) {
    if (!this.cats) {
      this.cats = new Map();
      for (const f of this.course.ix.families.values()) for (const m of f.mistakeCategories) if (!this.cats.has(m.id)) this.cats.set(m.id, { label: m.description, tip: m.feedback });
    }
    return this.cats.get(id) ?? null;
  }

  /** The Revise hub: what is weak, what is due, what has simply not been tested yet (kept apart), who is improving, and any session to resume. */
  overview(userId: string) {
    const all = this.insights(userId);
    const lt = learnerTime(this.db, this.clock, userId);
    const open = this.openRow(userId);
    const slim = (c: ConceptInsight) => ({ conceptId: c.conceptId, title: c.title, grade: c.grade, status: c.status, trend: c.trend, reasons: c.reasons, topMistake: c.topMistake, lessons: c.lessons, examWeak: c.examWeak });
    return {
      today: lt.date,
      taughtConcepts: all.length,
      open: open ? { id: open.id, mode: open.mode, startedAt: open.started_at } : null,
      weak: all.filter((c) => c.status === "weak").map(slim),
      due: all.filter((c) => c.status === "due").map(slim),
      untested: all.filter((c) => c.status === "untested").map(slim),
      improving: all.filter((c) => c.trend === "improving").map(slim),
      solid: all.filter((c) => c.status === "solid").length,
      quick: { minutes: [3, 5, 10], defaultMinutes: this.cfg.revision.defaultMinutes, questionsFor: Object.fromEntries([3, 5, 10].map((m) => [m, this.questionsFor(m)])) },
      history: this.history(userId),
    };
  }

  /** What Explore can offer: only grades, units and topics the learner may use now (taught, or below a placement), with question types. */
  explore(userId: string) {
    const access = this.accessSet(userId);
    const insights = new Map(this.insights(userId).map((c) => [c.conceptId, c]));
    const grades = this.course.view.worlds.map((w) => {
      const units = w.units.map((u) => {
        const ids = [...new Set(u.nodeIds.flatMap((id) => this.course.ix.nodeById.get(id)?.conceptIds ?? []))];
        const concepts = ids.filter((id) => insights.has(id)).map((id) => ({ conceptId: id, title: insights.get(id)!.title, status: insights.get(id)!.status }));
        return { unitId: u.id, title: u.learnerTitle, concepts };
      });
      return { grade: w.grade, title: w.learnerTitle, units: units.filter((u) => u.concepts.length), available: units.some((u) => u.concepts.length) };
    });
    const families = new Map<string, { familyId: string; title: string; concepts: Set<string> }>();
    for (const c of insights.values()) {
      for (const cand of this.engagement.review.candidates(c.conceptId, access.nodes)) {
        const fam = this.course.ix.families.get(this.course.ix.templates.get(cand.templateId)?.familyId ?? "");
        if (!fam) continue;
        const f = families.get(fam.id) ?? { familyId: fam.id, title: fam.title, concepts: new Set<string>() };
        f.concepts.add(c.conceptId);
        families.set(fam.id, f);
      }
    }
    return { grades, families: [...families.values()].map((f) => ({ familyId: f.familyId, title: f.title, topics: f.concepts.size })).sort((a, b) => a.title.localeCompare(b.title)), placedGrade: access.placed };
  }

  // ---- building a session ---------------------------------------------------------------------------------------------------

  questionsFor(minutes: number): number {
    return Math.max(3, Math.round((minutes * 60) / this.cfg.revision.secondsPerQuestion));
  }

  private openRow(userId: string): Row | undefined {
    return this.db.prepare("SELECT * FROM revision_sessions WHERE user_id = ? AND status = 'open'").get(userId) as Row | undefined;
  }
  private rowOf(userId: string, id: string): Row {
    const r = this.db.prepare("SELECT * FROM revision_sessions WHERE user_id = ? AND id = ?").get(userId, id) as Row | undefined;
    if (!r) throw new ApiError(404, "not_found", "That revision session does not exist.");
    return r;
  }

  /**
   * Build the items: concepts in priority order, round-robin so the same topic is not asked twice running, each item from a different
   * template than the concept's previous item where one exists, and never a question the learner has already met (same music and answer under any seed)
   * while a new one can be made.
   */
  private build(userId: string, sessionId: string, concepts: ConceptInsight[], total: number, perConcept: number, reason: RevItem["reason"] | ((c: ConceptInsight) => RevItem["reason"]), familyId?: string): RevItem[] {
    const access = this.accessSet(userId).nodes;
    const avoid = new Set<string>();
    const plans = concepts.map((c) => {
      let cands = this.engagement.review.candidates(c.conceptId, access);
      if (familyId) cands = cands.filter((x) => this.course.ix.templates.get(x.templateId)?.familyId === familyId);
      const last = new Map((this.db.prepare("SELECT template_id, MAX(created_at) AS at FROM revision_attempts WHERE user_id = ? AND concept_id = ? GROUP BY template_id").all(userId, c.conceptId) as Array<{ template_id: string; at: string }>).map((r) => [r.template_id, r.at]));
      // Least recently used template first; ties by id, so the order is deterministic.
      cands = [...cands].sort((a, b) => (last.get(a.templateId) ?? "").localeCompare(last.get(b.templateId) ?? "") || a.templateId.localeCompare(b.templateId));
      for (const k of this.engagement.mastery.seenKeys(userId, c.conceptId)) avoid.add(k);
      return { c, cands, made: 0 };
    });
    const items: RevItem[] = [];
    // Fill to the length asked for: a topic whose question type cannot make a fresh question just now (or can only repeat one) must not leave the session short, so each
    // further round lets every topic try again, and no question already in the session is ever added twice.
    const usedKeys = new Set<string>();
    for (let round = 0; round < 6 && items.length < total; round++) {
      const cap = perConcept + round;
      for (const p of plans) {
        if (items.length >= total) break;
        if (p.made >= cap || !p.cands.length) continue;
        const cand: Candidate = p.cands[p.made % p.cands.length]!;
        const gen = this.engagement.review.generateFor(cand, p.c.conceptId, seedFor(sessionId, p.c.conceptId, cand.templateId, p.made), avoid);
        const g = gen && parseGeneratedItemId(gen.item.id);
        p.made++;
        if (!gen || !g) continue;
        const key = questionKey(gen.item);
        if (usedKeys.has(key)) continue;
        usedKeys.add(key);
        avoid.add(key);
        items.push({
          itemId: gen.item.id,
          kind: "review",
          conceptId: p.c.conceptId,
          nodeId: cand.nodeId,
          templateId: cand.templateId,
          templateVersion: gen.item.templateVersion,
          seed: gen.seed,
          fingerprint: g.fingerprint,
          reason: typeof reason === "function" ? reason(p.c) : reason,
        });
      }
    }
    return items;
  }

  /**
   * Start or resume. At most one revision session is open per learner (on any device): asking again returns it, `resumed: true`. A request that
   * cannot be answered returns `{ session: null, reason }` with a reason the screen can explain; it never invents work.
   */
  start(userId: string, mode: RevisionMode, params: RevisionParams = {}) {
    const open = this.openRow(userId);
    if (open) return { session: this.view(userId, open.id), reason: null, resumed: true, mode: open.mode };
    const lt = learnerTime(this.db, this.clock, userId);
    const insights = this.insights(userId);
    if (!insights.length) return { session: null, reason: "nothing_taught" as const, resumed: false, mode };
    const minutes = Math.min(this.cfg.revision.maxMinutes, Math.max(this.cfg.revision.minMinutes, Math.round(params.minutes ?? this.cfg.revision.defaultMinutes)));
    const id = crypto.randomUUID();
    let items: RevItem[] = [];
    let used: RevisionParams = { ...params };
    if (mode === "quick") {
      const total = this.questionsFor(minutes);
      const per = total >= 8 ? 2 : 1;
      // Priority first (weak, then due), then topped up so the session is always the length that was asked for: topics never tested, then those
      // still being learned, then solid ones that have gone longest without a check. Nothing here is invented: every topic is one that was taught.
      const urgent = insights.filter((c) => c.status === "weak" || c.status === "due");
      const rest = [...insights.filter((c) => c.status === "untested"), ...insights.filter((c) => c.status === "learning"), ...insights.filter((c) => c.status === "solid")];
      const chosen = [...urgent, ...rest].slice(0, Math.ceil(total / per) + 3);
      items = this.build(userId, id, chosen, total, per, (c) => (c.status === "weak" ? "weak" : c.status === "due" ? "due" : c.status === "untested" ? "untested" : "keep-fresh"));
      used = { minutes };
    } else if (mode === "weak") {
      const weak = insights.filter((c) => c.status === "weak");
      const chosen = params.conceptId ? weak.filter((c) => c.conceptId === params.conceptId) : weak.slice(0, 3);
      if (!chosen.length) return { session: null, reason: params.conceptId ? ("not_weak" as const) : ("no_weak_topics" as const), resumed: false, mode };
      items = this.build(userId, id, chosen, chosen.length * 4, 4, "weak");
    } else {
      let pool = insights;
      if (params.conceptId) pool = pool.filter((c) => c.conceptId === params.conceptId);
      if (params.grade) pool = pool.filter((c) => c.grade === params.grade);
      if (params.unitId) {
        const unit = this.course.view.worlds.flatMap((w) => w.units).find((u) => u.id === params.unitId);
        const ids = new Set((unit?.nodeIds ?? []).flatMap((nid) => this.course.ix.nodeById.get(nid)?.conceptIds ?? []));
        pool = pool.filter((c) => ids.has(c.conceptId));
      }
      if (params.familyId) {
        const access = this.accessSet(userId).nodes;
        pool = pool.filter((c) => this.engagement.review.candidates(c.conceptId, access).some((x) => this.course.ix.templates.get(x.templateId)?.familyId === params.familyId));
      }
      if (!pool.length) return { session: null, reason: "nothing_available" as const, resumed: false, mode };
      const total = this.questionsFor(minutes);
      if (mode === "mixed") {
        // Interleave across domains: one topic from each domain in turn, so neighbouring questions ask for different kinds of thinking.
        const byDomain = new Map<string, ConceptInsight[]>();
        for (const c of pool) byDomain.set(c.domain, [...(byDomain.get(c.domain) ?? []), c]);
        const queues = [...byDomain.values()].map((q) => [...q].sort((a, b) => hashLike(`${id}${a.conceptId}`) - hashLike(`${id}${b.conceptId}`)));
        const mixed: ConceptInsight[] = [];
        while (mixed.length < total && queues.some((q) => q.length)) for (const q of queues) if (q.length && mixed.length < total) mixed.push(q.shift()!);
        items = this.build(userId, id, mixed, total, 1, "mixed", params.familyId);
      } else {
        const chosen = [...pool].sort((a, b) => b.priority - a.priority).slice(0, Math.max(1, Math.ceil(total / 2)));
        items = this.build(userId, id, chosen, total, 2, "explore", params.familyId);
      }
      used = { ...params, minutes };
    }
    if (!items.length) return { session: null, reason: "no_questions_yet" as const, resumed: false, mode };
    tx(this.db, () => {
      this.db
        .prepare("INSERT INTO revision_sessions (user_id,id,mode,status,params,started_at,local_date,timezone,curriculum_version,rules_version,items) VALUES (?,?,?,'open',?,?,?,?,?,?,?)")
        .run(userId, id, mode, JSON.stringify(used), lt.iso, lt.date, lt.tz, this.course.version, this.engagement.mastery.rules.rulesVersion, JSON.stringify(items));
    });
    return { session: this.view(userId, id), reason: null, resumed: false, mode };
  }

  // ---- playing ------------------------------------------------------------------------------------------------------------------

  private attemptsFor(userId: string, sessionId: string) {
    const rows = this.db.prepare("SELECT item_id, correct, attempt_number FROM revision_attempts WHERE user_id = ? AND session_id = ? ORDER BY attempt_number").all(userId, sessionId) as Array<{ item_id: string; correct: number; attempt_number: number }>;
    const by = new Map<string, { attempts: number; correct: boolean; firstTry: boolean }>();
    for (const r of rows) {
      const s = by.get(r.item_id) ?? { attempts: 0, correct: false, firstTry: false };
      s.attempts = Math.max(s.attempts, r.attempt_number);
      if (r.correct) s.correct = true;
      if (r.attempt_number === 1 && r.correct) s.firstTry = true;
      by.set(r.item_id, s);
    }
    return by;
  }

  view(userId: string, id: string) {
    const row = this.rowOf(userId, id);
    let items = JSON.parse(row.items) as RevItem[];
    if (row.status === "open") {
      let changed = false;
      items = items.map((si) => {
        if (si.stale || this.engagement.review.resolve(si)) return si;
        changed = true;
        return { ...si, stale: true };
      });
      if (changed) this.db.prepare("UPDATE revision_sessions SET items = ? WHERE user_id = ? AND id = ?").run(JSON.stringify(items), userId, id);
    }
    const attempts = this.attemptsFor(userId, id);
    const live = items.filter((i) => !i.stale);
    const params = JSON.parse(row.params) as RevisionParams;
    const concepts = [...new Set(live.map((i) => i.conceptId))];
    const insights = new Map(this.insights(userId).map((c) => [c.conceptId, c]));
    return {
      id: row.id,
      mode: row.mode,
      status: row.status,
      startedAt: row.started_at,
      params,
      /** Weak-topic practice shows the explanation (and the lesson to revisit) BEFORE the questions. */
      preface: row.mode === "weak" ? concepts.map((cid) => {
        const c = this.course.ix.concepts.get(cid);
        const ins = insights.get(cid);
        return { conceptId: cid, title: c?.title ?? cid, summary: c?.summary ?? "", reasons: ins?.reasons ?? [], topMistake: ins?.topMistake ?? null, lessons: this.lessonsOf(cid) };
      }) : [],
      items: row.status !== "open" ? [] : live.map((si) => {
        const r = this.engagement.review.resolve(si)!;
        const learner: LearnerItem = { ...this.course.learnerItem(r.item, "practice", r.scope), hintCount: 0, evidence: row.mode === "weak" ? "learning" : "independent" };
        const a = attempts.get(si.itemId);
        return { item: learner, conceptId: si.conceptId, conceptTitle: this.course.ix.concepts.get(si.conceptId)?.title ?? si.conceptId, reason: si.reason, answered: Boolean(a?.attempts), correct: Boolean(a?.correct), attempts: a?.attempts ?? 0, firstTry: Boolean(a?.firstTry) };
      }),
      summary: row.summary ? (JSON.parse(row.summary) as RevisionSummary) : null,
    };
  }

  attempt(userId: string, sessionId: string, attemptId: string, itemId: string, response: Response) {
    const row = this.rowOf(userId, sessionId);
    const prior = this.db.prepare("SELECT session_id, item_id, response, correct, mistake_category, attempt_number FROM revision_attempts WHERE user_id = ? AND id = ?").get(userId, attemptId) as
      | { session_id: string; item_id: string; response: string; correct: number; mistake_category: string | null; attempt_number: number }
      | undefined;
    const items = JSON.parse(row.items) as RevItem[];
    const si = items.find((i) => i.itemId === itemId && !i.stale);
    const r = si && this.engagement.review.resolve(si);
    if (prior) {
      if (prior.session_id !== sessionId || prior.item_id !== itemId || prior.response !== JSON.stringify(response)) throw new ApiError(409, "attempt_conflict", "That attempt id was already used for a different answer. Check again to send a new one.");
      return this.reply(si!, r!, prior.correct === 1, prior.mistake_category, prior.attempt_number, true, gradeResponse(this.course.ix, r!.item, response, r!.scope));
    }
    if (row.status !== "open") throw new ApiError(409, "session_closed", "This revision session has finished. Start a new one.");
    if (!si) throw new ApiError(404, "not_found", "Unknown question.");
    if (!r) throw new ApiError(409, "stale_item", "This question has been updated. Reopen the session.");
    const graded = gradeResponse(this.course.ix, r.item, response, r.scope);
    const lt = learnerTime(this.db, this.clock, userId);
    const n = tx(this.db, () => {
      const cur = this.rowOf(userId, sessionId);
      if (cur.status !== "open") throw new ApiError(409, "session_closed", "This revision session has finished. Start a new one.");
      const k = (this.db.prepare("SELECT COALESCE(MAX(attempt_number),0) AS n FROM revision_attempts WHERE user_id = ? AND session_id = ? AND item_id = ?").get(userId, sessionId, itemId) as { n: number }).n + 1;
      this.db.prepare("INSERT INTO revision_attempts (user_id,id,session_id,item_id,concept_id,template_id,template_version,seed,response,correct,mistake_category,attempt_number,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)").run(userId, attemptId, sessionId, itemId, si.conceptId, si.templateId, si.templateVersion, si.seed, JSON.stringify(response), graded.correct ? 1 : 0, graded.category, k, lt.iso);
      // Only the first answer is evidence. Weak-topic practice follows an explanation, so it is learning, never mastery evidence.
      if (k === 1) {
        this.engagement.mastery.record(userId, {
          id: `revision:${attemptId}`,
          conceptIds: [si.conceptId],
          source: row.mode === "weak" ? "remedial-step" : "review-item",
          correct: graded.correct,
          itemId,
          questionKey: questionKey(r.item),
          visibleKey: visibleKey(r.item),
          templateId: si.templateId,
          templateVersion: si.templateVersion,
          seed: si.seed,
          nodeId: si.nodeId,
          sessionId,
          mistakeCategory: graded.category,
        });
      }
      return k;
    });
    return this.reply(si, r, graded.correct, graded.category, n, false, graded);
  }

  private reply(_si: RevItem, r: { item: import("@mtp/curriculum").ExerciseItem; scope: import("@mtp/curriculum").MusicScope }, correct: boolean, category: string | null, attemptNumber: number, replayed: boolean, graded: ReturnType<typeof gradeResponse>) {
    const solution = revealSolution(this.course.ix, r.item, r.scope, correct, attemptNumber);
    return {
      correct,
      category,
      message: graded.message,
      reason: correct ? null : graded.reason,
      ...(graded.marks ? { marks: graded.marks } : {}),
      ...(graded.parts ? { parts: graded.parts.map((p) => ({ id: p.id, correct: p.correct, reason: p.reason })) } : {}),
      ...(solution ? { solution } : {}),
      attemptNumber,
      replayed,
    };
  }

  /**
   * Finish. Finishing early is always allowed and costs nothing: whatever was answered stays on record, nothing is marked wrong for what was
   * not reached. The session pays XP and counts for the daily goal once, only when at least `minAnsweredForCredit` questions were answered (or
   * all of them, if there were fewer); the ledger is keyed on the session, so a retried finish repeats the same reply.
   */
  complete(userId: string, sessionId: string) {
    const lt = learnerTime(this.db, this.clock, userId);
    const key = `revision:${sessionId}`;
    return tx(this.db, () => {
      const row = this.rowOf(userId, sessionId);
      if (row.status === "complete") {
        const xp = this.engagement.xp.find(userId, key);
        return { ...(JSON.parse(row.summary!) as RevisionSummary), alreadyComplete: true, xp: xp ?? null };
      }
      if (row.status !== "open") throw new ApiError(409, "session_closed", "This revision session was closed. Start a new one.");
      const items = (JSON.parse(row.items) as RevItem[]).filter((i) => !i.stale);
      const by = this.attemptsFor(userId, sessionId);
      const answered = items.filter((i) => by.get(i.itemId)?.attempts);
      const trends = new Map(this.insights(userId).map((c) => [c.conceptId, c.trend]));
      const credited = answered.length >= Math.min(this.cfg.revision.minAnsweredForCredit, items.length) && answered.length > 0;
      const concepts = [...new Set(answered.map((i) => i.conceptId))].map((cid) => {
        const mine = answered.filter((i) => i.conceptId === cid);
        const ok = mine.filter((i) => by.get(i.itemId)?.firstTry).length;
        return { conceptId: cid, title: this.course.ix.concepts.get(cid)?.title ?? cid, answered: mine.length, firstTryCorrect: ok, before: (trends.get(cid) ?? "none") as Trend | "none", verdict: ok === mine.length ? ("solid" as const) : ("needs-practice" as const), lessons: ok === mine.length ? [] : this.lessonsOf(cid) };
      });
      const summary: RevisionSummary = { mode: row.mode, questions: items.length, answered: answered.length, firstTryCorrect: answered.filter((i) => by.get(i.itemId)?.firstTry).length, finishedEarly: answered.length < items.length, credited, concepts, today: lt.date };
      this.db.prepare("UPDATE revision_sessions SET status = 'complete', completed_at = ?, summary = ? WHERE user_id = ? AND id = ?").run(lt.iso, JSON.stringify(summary), userId, sessionId);
      let xp = null;
      if (credited) {
        xp = this.engagement.xp.award(userId, { sourceKey: key, kind: "review_session", nodeId: REVIEW_NODE, nodeType: "review", curriculumVersion: this.course.version }, lt);
        this.engagement.activity.record(userId, { sourceKey: key, kind: "review_session", nodeId: REVIEW_NODE }, lt);
        this.engagement.achievements.evaluate(userId, this.engagement.mastery.all(userId, lt.date), key, lt.iso);
      }
      return { ...summary, alreadyComplete: false, xp };
    });
  }

  /** Leave without finishing. Answers stay on record; nothing is awarded and nothing is penalised. Idempotent. */
  abandon(userId: string, sessionId: string) {
    const row = this.rowOf(userId, sessionId);
    if (row.status === "open") this.db.prepare("UPDATE revision_sessions SET status = 'abandoned', completed_at = ? WHERE user_id = ? AND id = ?").run(this.clock.now().toISOString(), userId, sessionId);
    return { ok: true as const, status: this.rowOf(userId, sessionId).status };
  }

  history(userId: string, limit = 5) {
    return (this.db.prepare("SELECT id, mode, completed_at, summary FROM revision_sessions WHERE user_id = ? AND status = 'complete' ORDER BY completed_at DESC LIMIT ?").all(userId, limit) as Array<{ id: string; mode: RevisionMode; completed_at: string; summary: string }>).map((r) => {
      const s = JSON.parse(r.summary) as RevisionSummary;
      return { id: r.id, mode: r.mode, completedAt: r.completed_at, answered: s.answered, firstTryCorrect: s.firstTryCorrect, finishedEarly: s.finishedEarly };
    });
  }
}
